// Why Code: merges and de-duplicates several Google result lists in a fixed order; no native node does that.
const s = $('Store Settings').first().json;
const host = (u) => { const m = String(u || '').match(/^https?:\/\/([^\/?#:]+)/i); return m ? m[1].replace(/^www\./, '').toLowerCase() : ''; };
const isPlatform = (h) => !h || s.platform_domains.some(p => h === p || h.endsWith('.' + p));
// Serper answers all queries in one call, one item per query: first the last-month results, then the same queries without a limit.
const items = $input.all().map(i => i.json).filter(j => Array.isArray(j.organic));
const half = Math.ceil(items.length / 2);
const lists = [...items.slice(0, half), ...items.slice(half)].map(j => j.organic);
// The subject's must-words (from the planner): a word with capitals must match exactly, a lower-case one in any case.
const must = [].concat((($('Plan Answer Search (via Ask Venice)').first().json.output || {}).must_words) || []).map(w => String(w).trim()).filter(Boolean);
const rx = must.map(w => new RegExp('(^|[^A-Za-z0-9])' + w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '($|[^A-Za-z0-9])', /[A-Z]/.test(w) ? '' : 'i'));
const about = (t) => !rx.length || rx.some(r => r.test(String(t || '')));
const seen = new Map();
// First the articles the run's posts link to (often the official page itself), at most 3; then Google.
for (const x of [].concat(s.posts || [])) {
  const url = String(x.linked_url || '').split('#')[0]; const h = host(url);
  if (!/^https?:/i.test(url) || isPlatform(h) || seen.has(url) || seen.size >= 3 || !about(x.title + ' ' + x.summary)) continue;
  seen.set(url, { url, domain: h, found_by: 'post', gdate: '', title: String(x.title || '').slice(0, 200), snippet: String(x.summary || '').slice(0, 400) });
}
// Take the top result of every list, then the second of every list, and so on, so each query gets its best pages in.
for (let r = 0; r < 10 && seen.size < s.max_pages; r++) {
  for (const list of lists) {
    const x = list[r]; if (!x || !x.link || !/^https?:/i.test(x.link)) continue;
    const url = x.link.split('#')[0]; const h = host(url);
    if (isPlatform(h) || seen.has(url) || !about(x.title + ' ' + x.snippet + ' ' + url)) continue;
    seen.set(url, { url, domain: h, found_by: 'serper', gdate: x.date || '', title: String(x.title || '').slice(0, 200), snippet: String(x.snippet || '').slice(0, 400) });
    if (seen.size >= s.max_pages) break;
  }
}
const list = [...seen.values()];
return [{ json: { candidates: list.map(({ title, snippet, ...c }) => c), snippets: list, count: list.length } }];

// Why Code: numbers the pages and builds the model's page list (text of read pages, Google's snippet for the others).
const snips = Object.fromEntries(($('Build Page List').first().json.snippets || []).map(x => [x.url, x]));
const read = Object.fromEntries($input.all().map(i => i.json).filter(p => p && p.url).map(p => [p.url, p]));
const pages = ($('Build Page List').first().json.snippets || []).map((c, i) => {
  const p = read[c.url] || {};
  const ok = p.read_status === 'read' && p.text;
  return { n: i + 1, url: c.url, domain: c.domain, title: c.title, published: p.published || '', date_from: p.date_from || '', read_status: p.read_status || 'not read',
    body: ok ? String(p.text).slice(0, 7000) : (c.title + '. ' + c.snippet) };
});
// The posts themselves count too, after the pages: what a post says is at best claimed (by its own team) or unverified.
const platform = { reddit: 'reddit.com', hacker_news: 'news.ycombinator.com', x: 'x.com' };
// The subject's must-words (from the planner): a word with capitals must match exactly, a lower-case one in any case.
const must = [].concat((($('Plan Answer Search (via Ask Venice)').first().json.output || {}).must_words) || []).map(w => String(w).trim()).filter(Boolean);
const rx = must.map(w => new RegExp('(^|[^A-Za-z0-9])' + w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '($|[^A-Za-z0-9])', /[A-Z]/.test(w) ? '' : 'i'));
const about = (t) => !rx.length || rx.some(r => r.test(String(t || '')));
[].concat($('Store Settings').first().json.posts || []).filter(x => about(x.title + ' ' + x.summary)).slice(0, 12).forEach(x => pages.push({ n: pages.length + 1, url: x.url, domain: platform[x.source] || x.source, title: x.title,
  published: String(x.published_at || '').slice(0, 10), date_from: x.published_at ? 'post' : '', read_status: 'post', body: x.title + (x.summary ? '. ' + x.summary : '') }));
const xesc = (t) => String(t || '').replace(/</g, '‹').replace(/>/g, '›');
const pages_xml = pages.map(p => `<page n="${p.n}" domain="${p.domain}" date="${p.published || 'date unknown'}" status="${p.read_status === 'read' ? 'read' : p.read_status === 'post' ? 'post' : 'snippet only'}">${xesc(p.body)}</page>`).join('\n');
return [{ json: { pages: pages.map(({ body, ...p }) => p), pages_xml: pages_xml || '(no pages found)' } }];

// Why Code: turns the model's page numbers into dated links and fixes the status words; the caller gets one answer object.
const s = $('Store Settings').first().json;
const plan = $('Plan Answer Search (via Ask Venice)').first().json.output || {};
const pages = $('Build Answer Input').first().json.pages || [];
const byN = Object.fromEntries(pages.map(p => [p.n, p]));
const out = $input.first().json.output || {};
const STATUS = ['confirmed', 'claimed', 'unverified'];
const items = [].concat(out.items || []).slice(0, 10).map(it => {
  const st = String(it.status || '').toLowerCase().trim();
  const links = [...new Set([].concat(it.sources || []))].map(n => byN[n]).filter(Boolean)
    .map(p => ({ url: p.url, domain: p.domain, date: p.published, date_from: p.date_from }));
  return { name: String(it.name || '').slice(0, 120), what: String(it.what || '').slice(0, 400), status: STATUS.includes(st) ? st : 'unverified', links };
}).filter(it => it.name);
return [{ json: { answer: { question: s.question, subject: plan.subject || '', answer_type: plan.answer_type || '', queries: [].concat(plan.queries || []),
  summary: String(out.summary || ''), items, gaps: String(out.gaps || ''),
  pages_read: pages.filter(p => p.read_status === 'read').length, pages_total: pages.filter(p => p.read_status !== 'post').length, posts_used: pages.filter(p => p.read_status === 'post').length } } }];
